-- 044b: Mosaic capacity PBI-parity metric view. DRAFT STATUS: edw_test only - do not promote to
-- edw_prod without approval. Generated by _gen_044_capacity_pbi.py - edit that, not this.
--
-- WHY: governed TBWU 26/Shift capacity measures for the Executive Dashboard Capacity page and Genie,
-- matching the PBI Mosaic Impact Report "Practice Summary" page at its defaults.
-- SOURCE: edw_test.enterprise_analytics.mosaic_capacity_pbi_shift_vw (044a), filtered to in_pbi_default
-- (Shifts with Baselines + report shift-length filter + Rank_TopN "All Shifts").
-- PBI parity: measures are PBI's AVERAGEX-per-shift definitions with Unit = TBWU 26/Shift. To match PBI
-- tables/totals also filter groups to `Has TBWU26 Baseline` = 1 (PBI visual filter Has_Baseline_For_Selected_Unit).
--
-- ADDITIVE ONLY: plain CREATE VIEW (no OR REPLACE).

CREATE VIEW edw_test.enterprise_analytics.mosaic_capacity_pbi_metric_view
COMMENT 'MOSAIC CAPACITY SEMANTIC LAYER - PBI Impact Report parity (draft, edw_test only). Per-shift TBWU 26 capacity vs baseline, utilization, efficiency and Mosaic share, averaged per shift exactly as the PBI Practice Summary page. Filter groups to Has TBWU26 Baseline = 1 to match PBI.'
WITH METRICS
LANGUAGE YAML
AS
$$
{version: 1.1, source: edw_test.enterprise_analytics.mosaic_capacity_pbi_shift_vw, filter: in_pbi_default, comment: 'Mosaic capacity per shift in TBWU 26 (PBI Mosaic Impact Report, Practice Summary defaults). See CREATE VIEW comment.', dimensions: [{name: Shift Date, expr: source.ShiftDate, comment: Shift date. Bind the dashboard Period filter here.}, {name: Month, expr: source.shift_month, comment: Calendar month of the shift (PBI Month slicer).}, {name: Local Region, expr: source.local_region, comment: '6 fixed regions (+ Matrix / Blank), exact copy of PBI ''0. Cur''[Local] keyed on Team.'}, {name: Area, expr: source.area, comment: 'Exact copy of PBI ''0. Cur''[Area] keyed on Team.'}, {name: Team, expr: source.Team, comment: Radiologist's roster team (Provider Practice sub-team).}, {name: Team Rolled Up, expr: source.team_rolled_up, comment: 'Provider Practice (PBI ''Team Rolled up'', via team_rollups).'}, {name: Local Practice, expr: source.localpractice, comment: 'Practice used for the PBI Practice Summary table rows (PBI ''0. Cur''[localpractice]).'}, {name: Radiologist, expr: source.Rad_name, comment: Radiologist name.}, {name: NPI, expr: CAST(source.NPI AS STRING), comment: Radiologist NPI.}, {name: Baseline Type, expr: source.Baseline_type, comment: 'How the shift baseline was set (Exact, Proxy, Manual Review, ...).'}, {name: Model, expr: source.model, comment: PBI Model (source Model_type).}, {name: Data Quality, expr: source.Shift_Data_Quality_Status, comment: Shift data quality status (PBI Time Series page filters to Good).}, {name: Shift Length (hours), expr: source.shift_length_rounded, comment: Shift length rounded to whole hours (PBI Shift Length Display).}], measures: [{name: Selected Shift Count, expr: COUNT(1), comment: 'Shifts in scope. = PBI [Selected Shift Ct].'}, {name: Average Baseline, expr: AVG(source.shift_baseline_RPWU), comment: 'Average TBWU 26 baseline per shift. = PBI [Average Baseline] with unit TBWU 26/Shift.'}, {name: New Capacity, expr: AVG(source.on_shift_capacity_RPWU), comment: 'Average TBWU 26 capacity per shift with Mosaic. = PBI [New Capacity].'}, {name: Addl Capacity Per Shift, expr: CASE WHEN AVG(source.shift_baseline_RPWU) IS NULL THEN NULL ELSE AVG(source.on_shift_capacity_RPWU) - AVG(source.shift_baseline_RPWU) END, comment: 'New Capacity - Average Baseline (TBWU 26 per shift). = PBI [Add''l Capacity/Shift]. Practices with >= 0 (rounded) are ''Successful''.'}, {name: Pct Addl Capacity, expr: '(AVG(source.on_shift_capacity_RPWU) - AVG(source.shift_baseline_RPWU)) / NULLIF(AVG(source.shift_baseline_RPWU), 0)', comment: 'Additional capacity as % of baseline. = PBI [% Add''l Capacity].'}, {name: Pct Mosaic, expr: 'SUM(source.on_shift_mosaic_cases) / NULLIF(SUM(source.on_shift_cases), 0)', comment: 'Share of on-shift cases read in Mosaic. = PBI [% Mosaic].'}, {name: Pct Mosaic Drafting, expr: 'SUM(source.on_shift_mosaic_drafting_cases) / NULLIF(SUM(source.on_shift_cases), 0)', comment: 'Share of on-shift cases drafted in Mosaic. = PBI [% Mosaic Drafting].'}, {name: New Efficiency, expr: AVG(CASE WHEN source.on_shift_efficiency_RPWU <= 1 THEN source.on_shift_efficiency_RPWU END), comment: 'Average per-shift efficiency (shifts with efficiency > 1 ignored, as PBI). = PBI [New Efficiency].'}, {name: New Utilization, expr: AVG(source.on_shift_utilization_RPWU_pct / 100), comment: 'Average per-shift utilization, 0-1. = PBI [New Utilization] with unit TBWU 26/Shift.'}, {name: Has TBWU26 Baseline, expr: MAX(CASE WHEN source.has_tbwu26 THEN 1 ELSE 0 END), comment: 1 if any shift in the group has a TBWU 26 baseline. PBI hides groups where this is 0 (e.g. Matrix) - filter on it to match PBI tables and totals.}, {name: Radiologist Count, expr: COUNT(DISTINCT source.NPI), comment: Distinct radiologists (NPI) with a shift in scope.}, {name: Data Through Date, expr: MAX(source.ShiftDate), comment: Latest shift date in the source.}]}
$$
